#include <iostream>
#include <sstream>

int main() {
    std::ostringstream oss1;  // Creates a string stream
    oss1 << "Hello, world!";  // Write to oss1

    std::ostringstream oss2;  // Another string stream

    oss2 = std::move(oss1);  // Move assignment: internally swaps oss1 and oss2
    // After this, oss2 contains the content of oss1, and oss1 is left in a valid but unspecified state

    std::cout << oss2.str();  // Outputs: Hello, world!
    return 0;
}
